<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';$u=require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='GET')json_out(['templates'=>$pdo->query("SELECT s.*,a.category,a.stack,a.description,a.demo_url,a.thumbnail,a.source_media_id FROM services s LEFT JOIN template_assets a ON a.service_id=s.id WHERE s.slug LIKE 'template-%' ORDER BY s.id DESC")->fetchAll(),'csrf'=>csrf_token()]);
require_method('POST');require_csrf();$d=json_body();$id=(int)($d['id']??0);$name=trim((string)($d['name']??''));$category=(string)($d['category']??'Website');$price=filter_var($d['price']??null,FILTER_VALIDATE_FLOAT);
if(!$name||text_len($name)>180||!in_array($category,['Website','App','Ecommerce','MusicArtist'],true)||$price===false||$price<=0||$price>100000)json_out(['error'=>'Check title, category and EUR price.'],422);
$demo=trim((string)($d['demo_url']??''));$thumb=trim((string)($d['thumbnail']??''));foreach([$demo,$thumb] as $url)if($url!==''&&!preg_match('#^(https://|/)[^\s<>"\']+$#',$url))json_out(['error'=>'Use HTTPS or a site image path.'],422);
$media=(string)($d['source_media_id']??'');if($media){$q=$pdo->prepare("SELECT id FROM customer_media WHERE id=? AND kind='template-source'");$q->execute([$media]);if(!$q->fetch())json_out(['error'=>'Upload the protected source ZIP first.'],422);}
if(($d['active']??false)&&!$media)json_out(['error'=>'A source ZIP is required before making a template purchasable.'],422);
$pdo->beginTransaction();try{if($id){$q=$pdo->prepare("SELECT id FROM services WHERE id=? AND slug LIKE 'template-%' FOR UPDATE");$q->execute([$id]);if(!$q->fetch()){$pdo->rollBack();json_out(['error'=>'Template not found.'],404);}$pdo->prepare('UPDATE services SET name=?,price=?,active=? WHERE id=?')->execute([$name,$price,!empty($d['active'])?1:0,$id]);}else{$pdo->prepare("INSERT INTO services(slug,name,price,pricing_mode,active) VALUES(?,?,?,'fixed',?)")->execute(['template-'.bin2hex(random_bytes(8)),$name,$price,!empty($d['active'])?1:0]);$id=(int)$pdo->lastInsertId();}
$pdo->prepare('INSERT INTO template_assets(service_id,category,stack,description,demo_url,thumbnail,source_media_id) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE category=VALUES(category),stack=VALUES(stack),description=VALUES(description),demo_url=VALUES(demo_url),thumbnail=VALUES(thumbnail),source_media_id=VALUES(source_media_id)')->execute([$id,$category,text_cut((string)($d['stack']??''),0,255),text_cut((string)($d['description']??''),0,10000),$demo,$thumb,$media?:null]);$pdo->commit();audit('template.saved',(int)$u['id'],['id'=>$id]);json_out(['ok'=>true,'id'=>$id]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
